suppressPackageStartupMessages({library(Seurat);library(jsonlite);library(ggplot2)})
root<-'/output';truth<-read.csv(file.path(root,'reference-truth.csv'));ref<-fromJSON(file.path(root,'reference-preregistered.json'));obj<-readRDS(file.path(root,'selected-checkpoint.rds'))$global
prediction<-setNames(as.character(obj$seurat_clusters),colnames(obj));cells<-intersect(truth$cell,names(prediction));y<-truth$label[match(cells,truth$cell)];z<-prediction[cells];tab<-table(reference=y,cluster=z)
choose2<-function(x)sum(x*(x-1)/2);n<-sum(tab);observed<-choose2(tab);a<-choose2(rowSums(tab));b<-choose2(colSums(tab));expected<-a*b/choose2(n);ari<-(observed-expected)/((a+b)/2-expected)
weights<-as.matrix(tab);if(ncol(weights)<nrow(weights))weights<-cbind(weights,matrix(0,nrow(weights),nrow(weights)-ncol(weights)))
best<-0;search<-function(row,used,total){if(row>nrow(weights)){best<<-max(best,total);return(invisible(NULL))};for(column in setdiff(seq_len(ncol(weights)),used))search(row+1,c(used,column),total+weights[row,column])};search(1,integer(),0)
criteria<-list(allCellsRetained=length(cells)==nrow(truth)&&setequal(colnames(obj),truth$cell),populationCountMatches=ncol(tab)==ref$criteria$population_count,adjustedRandIndexPass=ari>=ref$criteria$adjusted_rand_index_min,bestOneToOneAccuracyPass=best/n>=ref$criteria$best_label_accuracy_min)
result<-list(reference=ref$source,scope='Complete post-QC single-cell population recovery; downstream extensions are not published-reference replications',referenceCells=nrow(truth),appCells=ncol(obj),referencePopulations=nrow(tab),appClusters=ncol(tab),adjustedRandIndex=ari,bestOneToOneAccuracy=best/n,manyToOnePurity=sum(apply(tab,2,max))/n,criteria=criteria,allPreregisteredCriteriaPass=all(unlist(criteria)),referenceCounts=as.list(rowSums(tab)),clusterSizes=as.list(colSums(tab)))
write_json(result,file.path(root,'reference-evaluation.json'),auto_unbox=TRUE,pretty=TRUE,digits=NA);write.csv(as.data.frame.matrix(tab),file.path(root,'reference-confusion-matrix.csv'))
frame<-as.data.frame(tab);p<-ggplot(frame,aes(cluster,reference,fill=Freq))+geom_tile(color='white',linewidth=.8)+geom_text(aes(label=Freq),size=5)+scale_fill_gradient(low='#f4f7fb',high='#3676ba')+theme_minimal(base_size=12)+theme(panel.grid=element_blank())+labs(title='Blinded MCP analysis versus withheld genotype labels',subtitle=sprintf('%d cells; ARI %.4f; one-to-one accuracy %.2f%%',n,ari,100*best/n),x='Agent-selected cluster',y='Withheld reference',fill='Cells',caption='Selection and analyst report frozen before scoring; modern Seurat environment.')
ggsave(file.path(root,'reference-comparison.png'),p,width=8,height=4.7,dpi=180,bg='white');print(result)
